        else
        {
            $this-&gt;response[&#039;html&#039;] = &#039;&lt;br&gt;&lt;size=&quot;10&quot;&gt;&lt;b&gt;&#039;.$lang[&#039;THANKS_NOT&#039;].&#039;&lt;/b&gt;&lt;/size&gt;&#039;;
        }
    }</pre>======================================<br />
